// Conformance table: every (code, value) row of number-format-oracle.json, generated by
// fixtures/xlsx/generators/build_numfmt_oracle.py. `libreoffice` is what LibreOffice shows, `expected` is the same
// unless Excel is known to differ (`excel: true`, with the reason in `note`).

import * as fs from 'fs';
import * as path from 'path';
import { formatValue } from './index';

interface Row {
  group: string;
  code: string;
  value: number | string;
  libreoffice: string;
  expected: string;
  excel?: boolean;
  unverified?: boolean;
  note?: string;
  dateSystem?: 1900 | 1904;
}

const table = JSON.parse(fs.readFileSync(path.join(__dirname, 'number-format-oracle.json'), 'utf8')) as {
  libreoffice: string;
  builtinSpelling: Record<string, string>;
  rows: Row[];
};
const show = (r: Row): string => formatValue(r.value, r.code, { dateSystem: r.dateSystem ?? 1900 }).text;

describe('number-format conformance table', () => {
  it('has at least 120 rows, from LibreOffice, and starts with the 33-code probe', () => {
    expect(table.rows.length).toBeGreaterThanOrEqual(120);
    expect(table.libreoffice).toMatch(/^\d+\.\d+/);
    expect(table.rows.slice(0, 99).every((r) => r.group === 'probe')).toBe(true);
    expect(new Set(table.rows.filter((r) => r.group === 'probe').map((r) => r.code)).size).toBe(33);
    expect(table.rows.filter((r) => r.group === 'probe').map((r) => r.value).slice(0, 3)).toEqual([1234.5678, -0.256, 46024.75]);
  });

  it('every row where Excel is expected to differ from LibreOffice says why, and only those rows differ', () => {
    for (const r of table.rows) {
      if (r.excel) {
        expect(r.note).toBeTruthy();
        expect(r.expected).not.toBe(r.libreoffice);
      } else {
        expect(r.expected).toBe(r.libreoffice);
      }
      if (r.unverified) expect(r.note).toBeTruthy();
    }
  });

  const groups = [...new Set(table.rows.map((r) => r.group))];
  it.each(groups)('group %s: the engine shows what the table expects', (group) => {
    const wrong = table.rows
      .filter((r) => r.group === group && show(r) !== r.expected)
      .map((r) => `${JSON.stringify(r.code)} ${JSON.stringify(r.value)}: got ${JSON.stringify(show(r))}, expected ${JSON.stringify(r.expected)}`);
    expect(wrong).toEqual([]);
  });

  it('tags the rows whose Excel behaviour is only assumed as unverified (pending real Excel files, plan D8)', () => {
    const unverified = table.rows.filter((r) => r.unverified);
    expect(unverified.length).toBeGreaterThan(0);
    // time rounding, the case of AM/PM and the sign of explicit-condition sections
    expect(unverified.some((r) => /round a time/.test(r.note!))).toBe(true);
    expect(unverified.some((r) => /AM\/PM/.test(r.note!))).toBe(true);
    expect(unverified.some((r) => r.group === 'conditions')).toBe(true);
    for (const r of table.rows.filter((x) => x.excel && /Excel keeps the minus sign/.test(x.note!))) expect(r.unverified).toBeUndefined();
  });

  it('strict LibreOffice-only agreement is the headline; the rows with self-authored Excel corrections are counted separately', () => {
    const agree = (rows: Row[]) => rows.filter((r) => show(r) === r.libreoffice).length;
    const probe = table.rows.filter((r) => r.group === 'probe');
    const corpus = table.rows.filter((r) => r.group === 'corpus');
    expect(probe).toHaveLength(99);
    expect(corpus).toHaveLength(240);
    // Raw agreement with LibreOffice: the rest are the rows flagged `excel` (negative and pre-1900-03 dates, time
    // rounding, the system date tokens): the table's expected string is the Excel one and the engine matches it.
    expect(agree(probe)).toBe(probe.filter((r) => !r.excel).length);
    expect(agree(corpus)).toBe(corpus.filter((r) => !r.excel).length);
    expect(agree(table.rows)).toBe(table.rows.filter((r) => !r.excel).length);
  });

  it('shows the corpus codes that the importer maps from built-in ids the way Excel shows them', () => {
    expect(table.builtinSpelling).toEqual({ 'mm-dd-yy': 'm/d/yyyy', 'm/d/yy h:mm': 'm/d/yyyy h:mm' });
    expect(table.rows.filter((r) => r.group === 'builtin')).toHaveLength(8);
  });
});
